{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 공영주차장을 민간업체에 맡긴 경우 주차장 관리에 대한 서울시장의 감독 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 공영주차장을 민간업체 등 관리수탁자에게 맡겼더라도 서울시장의 주차장 관리에 관한 지도·감독은 없어지지 않는다. 서울특별시 주차장 설치 및 관리 조례 제11조는 시장이 제10조에 따른 관리수탁자에 대하여 주차장관리에 관한 사항을 지도·감독한다고 정하고 있다. 따라서 관리수탁자가 공영주차장 관리를 위탁받았더라도 시장은 주차장 관리에 관한 사항을 지도·감독할 수 있다.",
          "b_ids": "주차장:제11조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
